/// <summary>
/// The MobDocPickOrder class is the document handler for all pick orders that should be made available on the pick order page.
/// </summary>
[TFMMenu('Pick',"@SYS50416","@MobileWMS:MobileWMS159",resourceStr(MobPickIcon),true,true,['MainMenu', 'Outbound'], true),
	TFMOrderListGetOrdersDocumentType('Pick',methodStr(MobDocPickOrder,GetPickOrders)),
    TFMOrderListGetOrderLinesDocumentType('Pick',methodStr(MobDocPickOrder,GetPickOrderLines)),
    TFMOrderListPostOrderDocumentType('Pick',methodStr(MobDocPickOrder,PostPickOrder))]
class MobDocPickOrder extends TFMDocumentHandler
{
    XML							returningXML;
    MobDocumentContentSubject	content;
    NoYes						pickListOperatorWorker;
    NoYes						pickListAccumulate;
    NoYes						salesAccumulate;
    NoYes						setCurrentDateWhenPostingFromDevice;
    NoYes						prodAccumulate;
    NoYes						prodCreateNew;
    NoYes						prodOprSegregate;
    NoYes						useTotePicking;
    NoYes						FinishRoute;
    NoYes						usePackingSlipForPickingList;
    str							toteGroupingField;
    WHSDefaultContainerTypeCode	defaultContainerType;
    Common						common;

}

